pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount, address caller) public {
        // Keep amount within balance-possible range (prevent overflow and revert due to insufficient balance)
        bound(amount, 0, address(c).balance);
        // Ensure caller is different from owner to detect violation of onlyOwner
        vm.assume(caller != c.owner());

        // Record owner before the call
        address recordedOwner = c.owner();

        // Provide Ether to contract so that sendMoney can proceed
        vm.deal(address(c), amount);

        // Prank as non-owner
        vm.prank(caller);
        bool ok = false;
        // Reference: sendMoney should revert for non-owner; buggy: succeeds.
        // We do NOT assert on revert; instead, we check a public state change that only an owner-call should produce.
        // Since a non-owner calling sendMoney in the reference cannot change any state, we check owner immutability.
        // But the only change sendMoney makes that can be observed is the decreasing Ether balance if the transfer succeeds.
        // However, the target is a fuzzed address (EOA), and calling it with .call{value} will always succeed.
        // The contract's balance can be checked, but it changes only if sendMoney succeeds and transfers Ether out.
        // For reference: sendMoney reverts for non-owner, so balance stays the same.
        // For buggy: sendMoney succeeds, balance decreases.
        // We need a balance check and a revert-safe wrapper.
        try c.sendMoney(target, amount) { ok = true; } catch { ok = false; }

        // Property: A non-owner call to sendMoney must not change the owner, and also must not execute successfully.
        // Since the directly state-changing effect is tricky, we rely on the fact that the onlyOwner modifier protects state changes:
        // the depositsCount does not change via sendMoney, and owner cannot change via sendMoney.
        // The difference is that caller can successfully transfer Ether only in buggy version.
        // So we assert: after a call by a non-owner, owner remains unchanged AND (if ok) balance decreased; but for reference, ok must be false.
        // To make a clean general rule: the contract's balance never decreases when a non-owner calls sendMoney.
        // That holds for reference (reverts, balance unchanged) and is violated by buggy (balance decreases).
        uint256 balanceAfter = address(c).balance;
        // Calculate expected balance: if sendMoney succeeded (buggy), balance decreases by amount; if failed (reference), unchanged.
        // We know reference makes ok false, so balanceAfter == balanceBefore (which is amount we funded).
        // But we need a single assertion that holds for ALL admissible inputs on reference, and fails for some on buggy.
        // Assert: address(c).balance == amount   (since we funded amount and no other operations; only sendMoney could decrease it).
        // Reference: sendMoney reverts, balance stays amount -> true.
        // Buggy: sendMoney succeeds, balance becomes 0 -> false.
        assertEq(balanceAfter, amount);
    }
}

