contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 sendAmount, uint256 withdrawAmount, address nonOwner) public {
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != address(0));
        vm.assume(withdrawAmount <= sendAmount);

        // fund the owner (this contract) and send money to the contract to have balance
        vm.deal(address(this), sendAmount);
        c.sendMoney(address(c), sendAmount);

        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();

        // nonOwner attempts to withdraw
        vm.deal(nonOwner, 0);
        vm.prank(nonOwner);
        try c.withdraw(withdrawAmount) {
            // if withdrawal succeeds (buggy version), balance drops and invariant may break
        } catch {
            // reference reverts for nonOwner, balance unchanged
        }

        uint256 balanceAfter = address(c).balance;
        uint256 depositsAfter = c.depositsCount();

        // Invariant: contract balance = (depositsCount + initial deposit from sendMoney) - owner withdrawn amounts
        // Since owner never withdrew here, balance must be sendAmount + depositsBefore (from fallback on sendMoney)
        // sendMoney triggers fallback, so depositsCount increases by 1.
        // After sendMoney: depositsCount = depositsBefore + 1, balance = sendAmount + (depositsBefore * 1 wei? No, fallback just increments count)
        // The invariant: balance == sendAmount (because depositsCount increments but no ether added except sendAmount)
        // Actually, the fallback increments depositsCount but does NOT receive ether from sendMoney, sendMoney sends to _target.
        // sendMoney(address(c), sendAmount) triggers fallback, increments depositsCount by 1, and balance increases by sendAmount.
        // So final balance should equal sendAmount + (any previous dust). Before sendMoney, balance was 0. So balance must be sendAmount.
        // If a nonOwner withdraw succeeds, balance decreases but depositsCount unchanged -> invariant broken.
        // General invariant: balance <= sendAmount && (balance == sendAmount if no owner withdraw)
        // Simpler: after sendMoney to self, balance == sendAmount + initial balance (0). If withdraw by nonOwner, balance < sendAmount.
        assertTrue(balanceAfter == sendAmount, "Invariant broken: non-owner withdrawal altered balance");
    }
}

